example.code:
#include <bitset>
#include <iostream>
#include <vector>

bool isPowerOfTwo(int x) {
    return x > 0 && (x & (x - 1)) == 0;
}

int main() {
    const int a = 12;
    const int b = 10;
    std::cout << "a & b = " << (a & b) << ' ' << std::bitset<4>(a & b) << '\n';
    std::cout << "a | b = " << (a | b) << ' ' << std::bitset<4>(a | b) << '\n';
    std::cout << "a ^ b = " << (a ^ b) << ' ' << std::bitset<4>(a ^ b) << '\n';
    std::cout << "~a = " << ~a << '\n';
    std::cout << "96 & 95 = " << (96 & 95) << '\n';

    std::cout << std::boolalpha;
    const std::vector<int> nums = {7, 10, 64, 96};
    for (int x : nums) {
        const bool odd = (x & 1) == 1;
        std::cout << x << ": " << (odd ? "odd" : "even")
                  << ", power of two: " << isPowerOfTwo(x) << '\n';
    }
    return 0;
}

