#include <bitset>
#include <iostream>

int main() {
    int flags = 0;
    flags |= (1 << 0);
    std::cout << "set 0: " << std::bitset<8>(flags) << '\n';
    flags |= (1 << 3);
    std::cout << "set 3: " << std::bitset<8>(flags) << '\n';
    std::cout << "bit 3: " << ((flags >> 3) & 1) << '\n';
    flags &= ~(1 << 0);
    std::cout << "clear 0: " << std::bitset<8>(flags) << '\n';
    flags ^= (1 << 1);
    std::cout << "toggle 1: " << std::bitset<8>(flags) << '\n';

    std::cout << "3 << 4 = " << (3 << 4) << '\n';
    std::cout << "100 >> 2 = " << (100 >> 2) << '\n';
    std::cout << "1LL << 40 = " << (1LL << 40) << '\n';
    return 0;
}

