#include <iostream>
#include <vector>

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> weights(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> weights[i];
    }
    int target = 0;
    std::cin >> target;

    int matches = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        int total = 0;
        for (int i = 0; i < n; ++i) {
            if ((mask >> i) & 1) {
                total += weights[i];
            }
        }
        if (total != target) {
            continue;
        }
        ++matches;
        std::cout << "size " << __builtin_popcount(mask) << ": ";
        bool first = true;
        for (int i = 0; i < n; ++i) {
            if ((mask >> i) & 1) {
                if (!first) {
                    std::cout << " + ";
                }
                std::cout << weights[i];
                first = false;
            }
        }
        std::cout << '\n';
    }
    std::cout << "count: " << matches << '\n';
    return 0;
}
